#thread to capture the process data
class DataCaptureThread(QThread):
    def __init__(self,method = None, *args, **kwargs):
        QThread.__init__(self, *args, **kwargs)
        self.method = method
        self.dataCollectionTimer = QtCore.QTimer()
        self.dataCollectionTimer.moveToThread(self)
        self.dataCollectionTimer.timeout.connect(self.method)
    def run(self):
        import threading
        threading.Thread(target = self.method).start()
        self.dataCollectionTimer.start(1000 * 60 * 1) # 1000 = 1s, initial with 1 minutes

        loop = QtCore.QEventLoop()
        loop.exec_()

# thread to update current time label
class CurrentTimeThread(QThread):
    def __init__(self,method = None, *args, **kwargs):
        QThread.__init__(self, *args, **kwargs)
        self.method = method
        self.CurrentTimeTimer = QtCore.QTimer()
        self.CurrentTimeTimer.moveToThread(self)
        self.CurrentTimeTimer.timeout.connect(self.method)
    def run(self):
        import threading
        threading.Thread(target = self.method).start()
        self.CurrentTimeTimer.start(1000) # 1000 = 1s, initial with 1s

        loop = QtCore.QEventLoop()
        loop.exec_()

