    # Data Collector Thread: get kW Data
    dataCollectionThread = DataCaptureThread(method = ui.refreshValue)
    dataCollectionThread.start()
    # Current Time Thread: Update Time Label
    currentTimeThread = CurrentTimeThread(method = ui.refreshTimeLabel)
    currentTimeThread.start()
    MainWindow.show()
    sys.exit(app.exec_())
